class Solution:
    def rob(self, nums: List[int]) -> int:
        n = len(nums)
        dp = [0] * (n + 1)              # dp[i]：前 i 间房最多偷多少
        dp[1] = nums[0]
        for i in range(2, n + 1):
            dp[i] = max(dp[i - 1],                  # 不偷第 i 间
                        dp[i - 2] + nums[i - 1])    # 偷第 i 间
        return dp[n]

