class Solution {
    public int rob(int[] nums) {
        int n = nums.length;
        int[] dp = new int[n + 1];              // dp[i]：前 i 间房最多偷多少
        dp[1] = nums[0];
        for (int i = 2; i <= n; i++) {
            dp[i] = Math.max(dp[i - 1],                 // 不偷第 i 间
                             dp[i - 2] + nums[i - 1]);  // 偷第 i 间
        }
        return dp[n];
    }
}

