class Solution:
    def rob(self, nums: List[int]) -> int:
        prev = cur = 0                      # dp[-1]（越界）和 dp[0]（没有房子），都是 0
        for x in nums:
            prev, cur = cur, max(cur, prev + x)     # 不偷：cur；偷：prev + x
        return cur

