class Solution {
    public int rob(int[] nums) {
        int prev = 0, cur = 0;                          // dp[-1]（越界）和 dp[0]（没有房子），都是 0
        for (int x : nums) {
            int next = Math.max(cur, prev + x);         // 不偷：cur；偷：prev + x
            prev = cur;
            cur = next;
        }
        return cur;
    }
}

